 JSONObject entry(String r,JSONObject meta,JSONObject release)throws Exception{JSONObject o=new JSONObject();o.put("repo",r);o.put("name",meta.optString("name",r));o.put("description",meta.optString("description", ""));JSONObject indexed=directory.get(r.toLowerCase(Locale.ROOT));if(indexed!=null){o.put("name",indexed.optString("name",o.optString("name")));o.put("iconPath",indexed.optString("iconPath"));o.put("iconHash",indexed.optString("iconHash"));}String identity=prefs.getString("pkg:"+r,"");if(!InstalledApps.validPackage(identity)&&indexed!=null)identity=indexed.optString("package");if(InstalledApps.validPackage(identity))o.put("package",identity);o.put("topics",meta.optJSONArray("topics")==null?new JSONArray():meta.optJSONArray("topics"));o.put("stars",meta.optLong("stargazers_count",indexed==null?0:indexed.optLong("stars")));o.put("popularityKnown",meta.has("stargazers_count")||(indexed!=null&&indexed.optBoolean("popularityKnown")));o.put("createdAt",meta.optString("created_at",indexed==null?"":indexed.optString("createdAt")));o.put("version",release.optString("tag_name"));o.put("changes",release.optString("body"));o.put("date",release.optString("published_at"));o.put("availability","published");o.put("checked",System.currentTimeMillis());o.put("missingSince",0);o.put("available",true);JSONArray apks=new JSONArray(),assets=release.optJSONArray("assets");if(assets!=null)for(int i=0;i<assets.length();i++){JSONObject a=assets.getJSONObject(i);if(a.optString("name").toLowerCase(Locale.ROOT).endsWith(".apk")&&a.optLong("size")<500L*1024*1024){JSONObject v=new JSONObject();v.put("id",a.getLong("id"));v.put("name",a.getString("name"));v.put("url",a.getString("browser_download_url"));v.put("size",a.optLong("size"));v.put("digest",a.optString("digest"));apks.put(v);}}o.put("assets",apks);if(apks.length()==0){o.put("available",false);o.put("availability","no_apk");}return o;}
 boolean blocked(String r){try{JSONArray a=new JSONArray(read(getAssets().open("blocked.json"),100000));for(int i=0;i<a.length();i++)if(r.equalsIgnoreCase(a.getString(i)))return true;}catch(Exception ignored){}return false;}
 void sync(String r)throws Exception{if(prefs.getStringSet("hidden",new HashSet<String>()).contains(r))return;if(blocked(r)){catalog.remove(r);return;}try{JSONObject known=directory.get(r.toLowerCase(Locale.ROOT));JSONObject m=known==null?get("repos/"+r):new JSONObject().put("name",known.optString("name",r)).put("description",known.optString("description")).put("topics",known.optJSONArray("topics")).put("created_at",known.optString("createdAt"));if(known!=null&&known.optBoolean("popularityKnown"))m.put("stargazers_count",known.optLong("stars"));JSONObject rel;try{rel=get("repos/"+r+"/releases/latest");}catch(ApiException absent){if(absent.code!=404)throw absent;rel=new JSONObject().put("assets",new JSONArray());}JSONObject o=entry(r,m,rel);catalog.put(r,o);}catch(ApiException e){JSONObject old=catalog.get(r);if(e.code==404&&old!=null){long since=old.optLong("missingSince");if(since==0)old.put("missingSince",System.currentTimeMillis());old.put("available",false);if(since>0&&System.currentTimeMillis()-since>6*3600000L)old.put("retired",true);}throw e;}}
