 @JavascriptInterface public void search(String term){String t=term.trim();if(t.length()<2||t.length()>80){status("Escribe entre 2 y 80 caracteres.");return;}final int generation=++searchGeneration;searches.execute(()->{if(generation!=searchGeneration)return;send("searching",true);try{String query=URLEncoder.encode(t,"UTF-8");JSONArray results=get("search/repositories?q="+query+"&sort=stars&per_page=30").getJSONArray("items");if(generation!=searchGeneration)return;for(int i=0;i<results.length();i++)rememberCandidate(results.getJSONObject(i));saveCandidates();publishDirectory();status(results.length()>0?"Resultados de GitHub añadidos. Abre una ficha para comprobar si tiene APK.":"No se encontraron proyectos para esta consulta.");}catch(Exception e){status(e.getMessage());}finally{if(generation==searchGeneration)send("searching",false);}});}

