 WebResourceResponse missingImage(){return new WebResourceResponse("text/plain","UTF-8",404,"Not Found",new HashMap<String,String>(),new ByteArrayInputStream(new byte[0]));}
 WebResourceResponse mediaResponse(String raw,String index){try{JSONObject a=sourceEntry(repo(raw));int n=Integer.parseInt(index);if(a==null||n<0||n>=a.getJSONArray("screenshots").length())return missingImage();JSONObject media=a.getJSONArray("screenshots").getJSONObject(n);return fdroidImage(media.getString("path"),media.getString("sha256"));}catch(Exception e){return missingImage();}}
