 WebResourceResponse fdroidImage(String path,String hash){try{if(!path.startsWith("/")||path.contains("..")||path.contains(":")||path.contains("?")||!hash.matches("[a-f0-9]{64}"))return missingImage();File dir=new File(getCacheDir(),"media");dir.mkdirs();File cache=new File(dir,hash);if(cache.isFile())return new WebResourceResponse("image/png",null,new FileInputStream(cache));URL url=new URL(new Uri.Builder().scheme("https").authority("f-droid.org").path("/repo"+path).build().toString());HttpURLConnection c=(HttpURLConnection)url.openConnection();c.setConnectTimeout(5000);c.setReadTimeout(7000);byte[] data;try{if(c.getResponseCode()!=200)return missingImage();try(InputStream in=c.getInputStream()){ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] buffer=new byte[8192];int n;while((n=in.read(buffer))!=-1){if(out.size()+n>6000000)return missingImage();out.write(buffer,0,n);}data=out.toByteArray();}}finally{c.disconnect();}if(!hex(MessageDigest.getInstance("SHA-256").digest(data)).equals(hash))return missingImage();BitmapFactory.Options opts=new BitmapFactory.Options();opts.inJustDecodeBounds=true;BitmapFactory.decodeByteArray(data,0,data.length,opts);if(opts.outWidth<1||opts.outWidth>8192||opts.outHeight>8192)return missingImage();try(OutputStream out=new FileOutputStream(cache)){out.write(data);}trimMediaCache(dir);return new WebResourceResponse("image/png",null,new ByteArrayInputStream(data));}catch(Exception e){return missingImage();}}
 void trimMediaCache(File dir){File[] files=dir.listFiles();if(files==null)return;long bytes=0;for(File f:files)bytes+=f.length();if(bytes<=100L*1024*1024)return;Arrays.sort(files,(a,b)->Long.compare(a.lastModified(),b.lastModified()));for(File f:files){long n=f.length();if(f.delete())bytes-=n;if(bytes<80L*1024*1024)break;}}
 javax.crypto.SecretKey tokenKey()throws Exception{java.security.KeyStore ks=java.security.KeyStore.getInstance("AndroidKeyStore");ks.load(null);if(!ks.containsAlias("kivo-token")){KeyGenerator g=KeyGenerator.getInstance(KeyProperties.KEY_ALGORITHM_AES,"AndroidKeyStore");g.init(new KeyGenParameterSpec.Builder("kivo-token",KeyProperties.PURPOSE_ENCRYPT|KeyProperties.PURPOSE_DECRYPT).setBlockModes(KeyProperties.BLOCK_MODE_GCM).setEncryptionPaddings(KeyProperties.ENCRYPTION_PADDING_NONE).build());g.generateKey();}return (javax.crypto.SecretKey)ks.getKey("kivo-token",null);}
