 void authState(){JSONObject a=new JSONObject();try{a.put("login",sessionToken.isEmpty()?"":prefs.getString("login",""));a.put("connected",!sessionToken.isEmpty()&&!prefs.getString("login","").isEmpty());a.put("pending",pendingAuthorization!=null||!sessionToken.isEmpty()&&prefs.getString("login","").isEmpty());}catch(Exception ignored){}send("auth",a);if(github!=null&&!local.isShutdown())local.execute(()->github.report(sessionToken));}
