 void loginDialog(){if(!sessionToken.isEmpty()&&prefs.getString("login","").isEmpty()){if(!authVerifying)verifyGithubUser(sessionToken,oauthGeneration,0);status("Recuperando tu perfil de GitHub…");return;}if(pendingAuthorization!=null){showAuthorization(pendingAuthorization);return;}String id=bundledOAuthClient();if(!id.isEmpty()){new AlertDialog.Builder(this).setTitle("Conectar GitHub").setMessage("Para publicar opiniones, GitHub solicitará public_repo: permite operar en repositorios públicos a los que tengas acceso. Kivo lo usa para su comunidad. Puedes elegir solo el catálogo, sin ese permiso. No se pide tu contraseña en Kivo.").setPositiveButton("Conectar para opinar",(d,w)->startDeviceFlow(id,true)).setNeutralButton("Solo catálogo",(d,w)->startDeviceFlow(id,false)).setNegativeButton("Cancelar",null).show();return;}new AlertDialog.Builder(this).setTitle("Conectar GitHub").setMessage("Kivo necesita su identificador público de aplicación. Puedes configurarlo o usar un token personal para pruebas.").setPositiveButton("Configurar acceso",(d,w)->oauthClientDialog()).setNeutralButton("Token personal",(d,w)->tokenDialog()).setNegativeButton("Cancelar",null).show();}

 void tokenDialog(){EditText field=new EditText(this);field.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD);field.setHint("Token personal de GitHub");field.setSingleLine(true);new AlertDialog.Builder(this).setTitle("Token personal de GitHub").setMessage("Se guarda cifrado en este dispositivo. Para el catálogo basta lectura. Publicar reseñas requiere un token autorizado para escribir comentarios en Issues del repositorio de comunidad. Puedes revocarlo en GitHub.").setView(field).setPositiveButton("Conectar",(d,w)->{final String candidate=field.getText().toString().trim();field.setText("");authJobs.execute(()->{String previous=sessionToken;try{if(candidate.isEmpty())throw new IOException();sessionToken=candidate;JSONObject user=get("user");storeToken(candidate);prefs.edit().putString("login",user.getString("login")).apply();authState();status("Cuenta conectada.");}catch(Exception e){sessionToken=previous;status("No se pudo verificar el token. Comprueba su validez y tu conexión.");}});}).setNegativeButton("Cancelar",null).show();}

