 JSONObject githubPost(String path,String body)throws Exception{HttpURLConnection c=(HttpURLConnection)new URL("https://github.com/"+path).openConnection();c.setInstanceFollowRedirects(false);c.setConnectTimeout(10000);c.setReadTimeout(15000);c.setRequestMethod("POST");c.setDoOutput(true);c.setRequestProperty("User-Agent","Kivo-Store/0.9.2");c.setRequestProperty("Accept","application/json");c.setRequestProperty("Content-Type","application/x-www-form-urlencoded");try{try(OutputStream out=c.getOutputStream()){out.write(body.getBytes("UTF-8"));}int code=c.getResponseCode();InputStream in=code>=400?c.getErrorStream():c.getInputStream();if(in==null)throw new IOException("GitHub no respondió a la autorización.");try(InputStream response=in){return OAuthProtocol.response(code,read(response,100000));}}finally{c.disconnect();}}
